mapper.select:
SELECT l.* FROM location l INNER JOIN campus c ON c.id = l.campus_id AND c.status = 1 INNER JOIN city ci ON ci.id = c.city_id AND ci.status = 1 WHERE l.status = 1
AND ( l.name LIKE CONCAT('%', #{keyword}, '%') OR l.address LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY l.sort_order ASC, l.id ASC LIMIT #{limit}
